/** Trusted React renderer for this Rich Catalog component. */
import React from "react"; import {useRichComponent} from "../../../binding.js"; export function Renderer({surface,component,basePath="/"}){const {properties:p}=useRichComponent(surface,component,basePath);const d=p.data??[],min=Math.min(...d.map(x=>x.value)),max=Math.max(...d.map(x=>x.value)),range=Math.max(1,max-min),pts=d.map((x,i)=>`${(i/Math.max(1,d.length-1))*100},${90-((x.value-min)/range)*75}`).join(" ");return <figure className="anu-rich-chart line"><figcaption><strong>{p.title}</strong>{p.subtitle&&<span>{p.subtitle}</span>}</figcaption><svg viewBox="0 0 100 100" role="img" aria-label={p.title} preserveAspectRatio="none"><polyline points={pts}/></svg><div className="chart-axis">{d.map(x=><small key={x.label}>{x.label}</small>)}</div></figure>}
